import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第二十四章","description":"《正易心法》第二十四章——画卦取象，本为特物：羲皇非出私意，特以顺时应物，见于日用；以钱博与优人呈伎二例说明行止坐卧皆是《易》，而百姓日用而罔觉。","frontmatter":{"title":"正易心法·第二十四章","description":"《正易心法》第二十四章——画卦取象，本为特物：羲皇非出私意，特以顺时应物，见于日用；以钱博与优人呈伎二例说明行止坐卧皆是《易》，而百姓日用而罔觉。","category":"guide","aliases":["正易心法第二十四章","画卦取象本为特物","见于日用"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-24.md","filePath":"yijing/zheng-yi-xin-fa/chapter-24.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-24.md"},x=p({...c,setup(u){const i=[{id:"z24-01",label:"一、本为特物",showLabel:!0,sentences:[["画卦取象，本为",{text:"特物",glossary:"tewu"},"。见于",{text:"曰用",glossary:"riyong"},"，无所不合。"]],note:["伏羲画卦取象，本来是为了特定的事物；它体现在日常生活之中，没有不符合的地方。（**本章是《正易心法》的「落地章」**：前二十三章讲象、数、本体、变复、文献批评，本章把它们全部落到最日常的地方——**《易》不在书本，在日用之间。**「曰用」的「曰」通「日」，即日用。）"]},{id:"z24-02",label:"二、顺时应物",showLabel:!0,sentences:[["羲皇画卦，非谓出私意。撰写一《易》道于",{text:"方册",glossary:"fangce"},"上，以诲人也。特以顺时应物，则以见于曰用之间耳。"]],note:["伏羲画卦，不是说他出于个人的私意，把一部《易》道写在书册上来教导人；只是顺应时机、应对万物，便体现在日常生活之间罢了。（**这是「发现」与「创造」之别**：伏羲不是「创作」卦画，而是「发现」了本来就存在于万物中的道理，用卦画的形式呈现出来。这与第二十章「本之自然」、第二十六章「气序自然」是同一个立场。）"]},{id:"z24-03",label:"三、钱博之喻",showLabel:!0,sentences:[["以",{text:"粗迹",glossary:"cuji"},"言之，如以",{text:"钱博",glossary:"qianbo"},"，六纯字，乾也。六纯背，坤也。",{text:"差互",glossary:"chahu"},"，六子也。若反则未胜，至纯则乾坤成矣。"]],note:["用粗浅的例子来说：比如用铜钱游戏——六枚全部字面朝上，是乾；六枚全部背面朝上，是坤；字背混杂参差，是六子；还有翻转未定则「未胜」，达到纯粹则乾坤成。（**日常游戏里，就演着第二十、二十一章的真体与假合**：「至纯」＝乾坤真体（有定实），「差互」＝六子假合（无定实）。）"]},{id:"z24-04",label:"四、优人之喻",showLabel:!0,sentences:[["又如",{text:"优人呈伎",glossary:"yourenChengji"},"，壮者任其难，六子也。老者",{text:"敛其利",glossary:"lianqili"},"，乾坤也。此皆理之自然。"]],note:["又比如艺人表演技艺：壮年人承担高难度的表演，是六子；老年人收取利益，是乾坤。这些都是自然之理。（**老者看似不动，但所有壮者的表演最终都是为老者服务的**——这正是第十章「圣人尽乾、贤人尽坤」与第十一章「破体炼之，纯体乃成」在日常生活中的影子。）"]},{id:"z24-05",label:"五、举天下皆易",showLabel:!0,sentences:[["即此理以察其余，则是行止坐卧",{text:"纤悉",glossary:"xianxi"},"举天下皆《易》，",{text:"无可拣择",glossary:"wukeJianze"},"者。"]],note:["用这个道理来观察其余的一切，那么行走、停止、坐下、躺卧，细微详尽，整个天下都是《易》，没有可以挑选排除的。（**「无可拣择」四个字很重**：不是「有些事是《易》，有些不是」，而是**没有一件事在《易》之外**——无从取舍，因为你取舍的每一个动作本身就在《易》中。）"]},{id:"z24-06",label:"六、百姓罔觉",showLabel:!0,sentences:[["但百姓",{text:"昏昏",glossary:"hunhun"},"，曰用之而",{text:"罔觉",glossary:"wangjue"},"矣。"]],note:["只是普通百姓懵懵懂懂，日日使用却不自知罢了。（《系辞传》说「百姓日用而不知」；麻衣改一字作「**罔觉**」——**「不知」是缺乏知识，「罔觉」是不自觉。** 百姓从未学过《易》，但他们的行止坐卧都在用《易》；**真正的问题不是「不知」，而是「昏昏」：处于混沌状态，感觉不到自己在用《易》。** 所以学《易》的目的，不是获得新知识，而是**从「昏昏」变成「觉」**。）"]}],o=[{id:"tewu",term:"特物",pinyin:"tè wù",meaning:"特定的事物。每个卦象对应特定的物象，非空言。"},{id:"riyong",term:"曰用",pinyin:"rì yòng",meaning:"日用，「曰」通「日」。体现在日常生活之中。"},{id:"fangce",term:"方册",pinyin:"fāng cè",meaning:"书册。古代书写用的方形木牍或书册。"},{id:"cuji",term:"粗迹",pinyin:"cū jì",meaning:"浅显的例子。粗迹是粗浅的痕迹，言下之意还有细迹。"},{id:"qianbo",term:"钱博",pinyin:"qián bó",meaning:"古代用铜钱游戏或占卜的方式。"},{id:"chahu",term:"差互",pinyin:"cī hù",meaning:"字背混杂，参差不一。即阴阳混杂，对应六子。"},{id:"yourenChengji",term:"优人呈伎",pinyin:"yōu rén chéng jì",meaning:"艺人表演技艺。优人是古代艺人、演员。"},{id:"lianqili",term:"敛其利",pinyin:"liǎn qí lì",meaning:"收取利益。老者不直接表演，却收取报酬——对应乾坤真体。"},{id:"xianxi",term:"纤悉",pinyin:"xiān xī",meaning:"细微详尽。纤是细小，悉是全部。"},{id:"wukeJianze",term:"无可拣择",pinyin:"wú kě jiǎn zé",meaning:"没有可以挑选排除的。《易》无处不在。"},{id:"hunhun",term:"昏昏",pinyin:"hūn hūn",meaning:"懵懵懂懂、不清醒、不自知的状态。"},{id:"wangjue",term:"罔觉",pinyin:"wǎng jué",meaning:"不自觉。罔是不，觉是察觉。麻衣改《系辞》「日用而不知」为「罔觉」。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",22)),e(r,{colophon:"本为特物 · 顺时应物 · 行止坐卧皆易 · 百姓罔觉",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十四章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「见于曰用」「曰用之而罔觉」之「曰」皆通「日」（日用），此处依底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"顺时应物",pinyin:["shùn","shí"],meaning:"伏羲画卦不是创作而是发现：顺应时机、应对万物，把本有的道理用卦画呈现出来。"},{term:"钱博",pinyin:["qián","bó"],meaning:"用铜钱游戏。六纯字＝乾，六纯背＝坤，差互＝六子——日常游戏中就演着真体与假合。"},{term:"优人呈伎",pinyin:["yōu","rén"],meaning:"艺人表演。壮者任难＝六子，老者敛利＝乾坤——老者不动，却是一切的根基。"},{term:"无可拣择",pinyin:["wú","kě"],meaning:"没有可以挑选排除的。《易》无处不在——不是「有些事是《易》」，而是没有一件事在《易》之外。"},{term:"百姓罔觉",pinyin:["wǎng","jué"],meaning:"麻衣改《系辞》「日用而不知」为「日用而罔觉」——「不知」是缺乏知识，「罔觉」是不自觉。"}]}),n[3]||(n[3]=t("",28))])}}});export{m as __pageData,x as default};
